package com.hmdp.ai.domain.knowledge;
import com.hmdp.ai.domain.artifact.Citation;import java.util.Collections;import java.util.LinkedHashMap;import java.util.Map;
public final class RetrievedChunk {private final KnowledgeChunk chunk;private final double score,vectorScore,lexicalScore,rerankScore;private final String text;private final Map<String,Object> metadata;private final Citation citation;public RetrievedChunk(KnowledgeChunk chunk,double score,double vectorScore,double lexicalScore,double rerankScore,String text,Map<String,Object> metadata,Citation citation){this.chunk=chunk;this.score=score;this.vectorScore=vectorScore;this.lexicalScore=lexicalScore;this.rerankScore=rerankScore;this.text=text;this.metadata=Collections.unmodifiableMap(new LinkedHashMap<>(metadata));this.citation=citation;}public KnowledgeChunk getChunk(){return chunk;}public double getScore(){return score;}public double getVectorScore(){return vectorScore;}public double getLexicalScore(){return lexicalScore;}public double getRerankScore(){return rerankScore;}public String getText(){return text;}public Map<String,Object> getMetadata(){return metadata;}public Citation getCitation(){return citation;}}
